import { ariaAttr, boolAttr, dataAttr } from "../../dom/attrs";
import type { NormalizeProps, PropTypes } from "../../machine/prop-types";
import type { Service } from "../../machine/types";
import { parts } from "./dialog.anatomy";
import {
  getActionTriggerId,
  getBackdropId,
  getCancelTriggerId,
  getCloseTriggerId,
  getContentId,
  getDescriptionId,
  getPositionerId,
  getTitleId,
  getTriggerId,
} from "./dialog.dom";
import type {
  DialogActionTriggerProps,
  DialogApi,
  DialogCancelTriggerProps,
  DialogSchema,
} from "./dialog.types";

export function connect<T extends PropTypes>(
  service: Service<DialogSchema>,
  normalize: NormalizeProps<T>,
): DialogApi<T> {
  const { context, prop, computed, send, scope } = service;

  const open = context.get("open");
  const modal = prop("modal");
  const presentation = computed("presentation");
  const disabled = prop("disabled");
  const state = open ? "open" : "closed";

  const contentId = getContentId(scope);
  const titleId = getTitleId(scope);
  const descriptionId = getDescriptionId(scope);

  // Both read from the DOM by the machine: an IDREF may only point at an id that
  // exists, and whether the consumer rendered a title is not ours to assume.
  const hasTitle = context.get("hasTitle");
  const describedBy = [
    context.get("hasDescription") ? descriptionId : undefined,
    prop("describedBy"),
  ]
    .filter((id): id is string => id !== undefined && id !== "")
    .join(" ");

  return {
    open,
    modal,
    presentation,

    setOpen(next: boolean): void {
      send({ type: "OPEN.SET", open: next });
    },

    dismiss(reason): void {
      send({ type: "CONTENT.DISMISS", reason });
    },

    focusInitial(): void {
      send({ type: "CONTENT.FOCUS" });
    },

    getTriggerProps: (): T["button"] =>
      normalize.button({
        ...parts.trigger.attrs,
        id: getTriggerId(scope),
        type: "button",
        disabled,
        "aria-haspopup": "dialog",
        "aria-expanded": boolAttr(open),
        // Only while open. A dangling IDREF names nothing, and it is the exact
        // value `aria-valid-attr-value` flags on a closed dialog.
        "aria-controls": open ? contentId : undefined,
        "data-state": state,
        "data-disabled": dataAttr(disabled),
        onClick(event) {
          if (event.defaultPrevented || disabled) return;
          send({ type: "TRIGGER.CLICK" });
        },
      }),

    getBackdropProps: (): T["element"] =>
      normalize.element({
        ...parts.backdrop.attrs,
        id: getBackdropId(scope),
        "aria-hidden": ariaAttr(true),
        "data-state": state,
        "data-presentation": presentation,
      }),

    // No ARIA, and no positioner primitive either: a dialog centres in CSS, it
    // computes nothing (spec §8, divergence 3). The part exists so that `drawer`
    // and `popover` can share the composition.
    getPositionerProps: (): T["element"] =>
      normalize.element({
        ...parts.positioner.attrs,
        id: getPositionerId(scope),
        "data-state": state,
        "data-presentation": presentation,
      }),

    getContentProps: (): T["element"] =>
      normalize.element({
        ...parts.content.attrs,
        id: contentId,
        role: prop("role"),
        dir: context.get("surfaceDir") ?? prop("dir"),
        // So focus has somewhere to land when the surface holds nothing tabbable.
        tabIndex: -1,
        "aria-modal": ariaAttr(modal),
        "aria-labelledby": hasTitle ? titleId : undefined,
        // Never both: one name, from the title when there is one.
        "aria-label": hasTitle ? undefined : prop("label"),
        "aria-describedby": describedBy === "" ? undefined : describedBy,
        "data-state": state,
        "data-modal": dataAttr(modal),
        "data-presentation": presentation,
        "data-nested": dataAttr(prop("parentId") !== undefined),
        // The DOM trap and the spatial trap are the same declaration (input.md §3.1).
        "data-snav": "container",
        "data-snav-trap": dataAttr(modal),
      }),

    getTitleProps: (): T["element"] => normalize.element({ ...parts.title.attrs, id: titleId }),

    getDescriptionProps: (): T["element"] =>
      normalize.element({ ...parts.description.attrs, id: descriptionId }),

    getCloseTriggerProps: (): T["button"] =>
      normalize.button({
        ...parts.closeTrigger.attrs,
        id: getCloseTriggerId(scope),
        type: "button",
        "data-state": state,
        onClick(event) {
          if (event.defaultPrevented) return;
          send({ type: "CLOSE.CLICK" });
        },
      }),

    // No id and no ARIA: the row is a box. It exists because touch platforms lay the two
    // choices out equal-width with one spacing, and that is
    // a rule the surface owes its actions rather than one each button can know.
    getActionsProps: (): T["element"] => normalize.element({ ...parts.actions.attrs }),

    // Both close, and both let the consumer keep the surface open by calling
    // `preventDefault()` — an action that awaits a request needs that, and it is
    // the same contract `closeTrigger` already publishes.
    getCancelTriggerProps: (cancelProps: DialogCancelTriggerProps = {}): T["button"] =>
      normalize.button({
        ...parts.cancelTrigger.attrs,
        id: getCancelTriggerId(scope, cancelProps.index),
        type: "button",
        "data-state": state,
        onClick(event) {
          if (event.defaultPrevented) return;
          send({ type: "CLOSE.CLICK" });
        },
      }),

    getActionTriggerProps: (actionProps: DialogActionTriggerProps = {}): T["button"] =>
      normalize.button({
        ...parts.actionTrigger.attrs,
        id: getActionTriggerId(scope, actionProps.index),
        type: "button",
        "data-state": state,
        "data-destructive": dataAttr(actionProps.destructive === true),
        onClick(event) {
          if (event.defaultPrevented) return;
          send({ type: "CLOSE.CLICK" });
        },
      }),
  };
}

import { query } from "../../dom/query";
import { getPartId } from "../../machine/ids";
import { getDocumentEl, type Scope } from "../../machine/scope";

const COMPONENT = "dialog";

export function getTriggerId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "trigger");
}

export function getBackdropId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "backdrop");
}

export function getPositionerId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "positioner");
}

export function getContentId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "content");
}

export function getTitleId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "title");
}

export function getDescriptionId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "description");
}

export function getCloseTriggerId(scope: Scope): string {
  return getPartId(scope, COMPONENT, "closeTrigger");
}

/**
 * The same key `getActionTriggerId` takes, and omitted for the FIRST way out of a
 * row on purpose — which is why this one cannot simply be keyed the way that one
 * was. `getCancelTriggerEl` below resolves an alert's initial focus by the
 * un-indexed id, and the order the sentence reads in puts the cancel second, so
 * indexing every cancel would hand the APG guarantee to whichever button happened
 * to be written first. Only the second and later ones need a key: they exist to be
 * distinct, not to be found.
 */
export function getCancelTriggerId(scope: Scope, index?: number | undefined): string {
  return getPartId(
    scope,
    COMPONENT,
    "cancelTrigger",
    index === undefined ? undefined : String(index),
  );
}

/**
 * `index` is what makes a row of answers possible, and it is spelled the way
 * `getSwatchId` spells the same question. An alert draws two answers — but without a key the third button repeats the second one's id: N buttons, one id,
 * and no detector in this repository could see it (audit of 2026-09-05).
 *
 * Omitted, the id is exactly the one this function has always returned, so every
 * pinned fixture and every single-action surface is untouched.
 */
export function getActionTriggerId(scope: Scope, index?: number | undefined): string {
  return getPartId(
    scope,
    COMPONENT,
    "actionTrigger",
    index === undefined ? undefined : String(index),
  );
}

export function getTriggerEl(scope: Scope): HTMLElement | null {
  return scope.getById(getTriggerId(scope));
}

export function getBackdropEl(scope: Scope): HTMLElement | null {
  return scope.getById(getBackdropId(scope));
}

export function getPositionerEl(scope: Scope): HTMLElement | null {
  return scope.getById(getPositionerId(scope));
}

/**
 * What `alert-dialog` points its default `initialFocus` at. The APG asks an alert
 * dialog to open on its least destructive action, and the machine's fallback —
 * the first tabbable inside the surface — is the opposite of that as soon as the
 * author writes the confirm button first, which reads naturally and is common.
 */
export function getCancelTriggerEl(scope: Scope): HTMLElement | null {
  return scope.getById(getCancelTriggerId(scope));
}

/**
 * Looked up by id rather than by walking down from anything: the surface is
 * portalled, so there is no ancestor to walk down from.
 */
export function getContentEl(scope: Scope): HTMLElement | null {
  return scope.getById(getContentId(scope));
}

/**
 * The node the environment is resolved against: the surface once it exists, the
 * trigger before it does, and the document's own root when neither is rendered —
 * a dialog driven from a store has no trigger at all.
 *
 * Deliberately not `scope.getDoc()`, which throws where there is no document. An
 * effect that reaches for one cannot be started in a plain node test, and every
 * machine in this library has to be.
 */
export function getEnvironmentEl(scope: Scope): HTMLElement | null {
  return getContentEl(scope) ?? getTriggerEl(scope) ?? getDocumentEl(scope);
}

/**
 * The anchor for the *direction* alone. It does not read the surface the way
 * `getEnvironmentEl` does: the surface is portalled into `body` and would only
 * report the document's direction back to itself. A dialog driven from a store
 * has no trigger either, and resolving against nothing answers `"ltr"` flat —
 * the one direction an RTL page did not ask for.
 */
export function getDirAnchorEl(scope: Scope): HTMLElement | null {
  return getTriggerEl(scope) ?? getDocumentEl(scope);
}

/**
 * `aria-labelledby` and `aria-describedby` may only point at ids that exist, and
 * whether the consumer rendered a title or a description is not something the
 * machine can assume — the same rule `field` and `toggle-group` follow.
 *
 * Scope-qualified: a dialog holds other components, and a popover nested in one
 * has a `title` of its own that an unqualified search would name the dialog after.
 */
export function hasPart(scope: Scope, part: string): boolean {
  return query(getContentEl(scope), `[data-part~="dialog:${part}"]`) !== null;
}

/**
 * The dialog, and the two decisions the rest of the overlay family inherits.
 *
 * **`context.open` is the only source of truth; the state is a projection of it.**
 * Transitions never target `open`/`closed` directly — they write the bindable, and
 * a `watch` sends `OPEN.SYNC` to move the state. One path in, one path out, and the
 * controlled semantics come for free: a consumer that declines to update `open`
 * keeps the dialog open, which is exactly what "controlled" is supposed to mean.
 *
 * **The order the effects install in is a contract, not a detail.** The interpreter
 * tears down in reverse, so `hideOutside` has to be *installed after* the focus
 * management in order to be *removed before* it — otherwise focus is handed back to
 * an element that is still `inert`, and the browser silently refuses it. Read the
 * `open` state's list bottom-up to see the teardown: parts, intents, the page given
 * back, focus restored, scroll released, layer popped.
 *
 * Nothing here is density-aware beyond `computed.presentation`, which exists only
 * to write `data-presentation`. A sheet and a centred modal are the same machine.
 */

import { hasAccessibleName } from "../../a11y/accessible-name";
import { hideOthers } from "../../a11y/aria-hidden";
import { lockScroll } from "../../a11y/scroll-lock";
import { observeChildren } from "../../dom/observers";
import { contains, query } from "../../dom/query";
import { resolveDir } from "../../dom/text-dir";
import {
  resolveEnvironment,
  trackEnvironment as watchEnvironment,
} from "../../environment/environment";
import { trapFocus } from "../../focus/focus-trap";
import { proxyTabFocus } from "../../focus/proxy-tab-focus";
import { restoreFocus } from "../../focus/restore-focus";
import { trackDismissableLayer } from "../../interaction/dismissable";
import { getLayerStack, isEscapeLikeDismissal } from "../../interaction/layer-stack";
import { createMachine } from "../../machine/create-machine";
import type { Scope } from "../../machine/scope";
import type { Machine } from "../../machine/types";
import { focusElement, getFirstTabbable, trackInputModality } from "../../nav";
import type { Density, Direction } from "../../types";
import { isDev } from "../../utils/env";
import { warn } from "../../utils/invariant";
import {
  getBackdropEl,
  getCancelTriggerEl,
  getContentEl,
  getContentId,
  getDirAnchorEl,
  getEnvironmentEl,
  getPositionerEl,
  getTriggerEl,
  hasPart,
} from "./dialog.dom";
import type { DialogRole, DialogSchema } from "./dialog.types";

/**
 * Where focus goes when the surface opens, before any fallback. An alert dialog
 * opens on its *least destructive* action (APG `alertdialog`), and the fallback
 * both callers share — the first tabbable inside the surface — is the opposite of
 * that the moment the author writes the confirm button first, which reads
 * naturally and is what people write. Returning `null` hands the decision back:
 * the trap falls through to its own first-tabbable, and so does `focusInitial`.
 */
function resolveInitialFocus(
  requested: (() => HTMLElement | null) | undefined,
  role: DialogRole,
  scope: Scope,
): HTMLElement | null {
  return requested?.() ?? (role === "alertdialog" ? getCancelTriggerEl(scope) : null);
}

export const machine: Machine<DialogSchema> = createMachine<DialogSchema>({
  props({ props }) {
    const modal = props.modal ?? true;
    const role = props.role ?? "dialog";
    return {
      defaultOpen: false,
      presentation: "auto",
      restoreFocus: true,
      preventScroll: true,
      closeOnEscape: true,
      disabled: false,
      intents: null,
      ...props,
      role,
      modal,
      // An alert dialog interrupts the workflow to get a decision, and the whole
      // point of the role is that you do not leave it by accident: a click in the
      // gutter must not cancel a destructive confirmation. Decided in the machine
      // rather than in a React wrapper so every adapter inherits it, and still
      // overridable — a consumer who passes `false` explicitly means it.
      closeOnInteractOutside: props.closeOnInteractOutside ?? role !== "alertdialog",
      // A non-modal surface leaves the page reachable on purpose, so a trap that
      // held Tab inside it would be lying about where the user is allowed to go.
      trapFocus: modal && (props.trapFocus ?? true),
    };
  },

  context({ prop, bindable }) {
    return {
      open: bindable<boolean>(() => ({
        defaultValue: prop("defaultOpen"),
        value: prop("open"),
        onChange: (open) => prop("onOpenChange")?.({ open }),
        debugLabel: "dialog open",
      })),
      density: bindable<Density>(() => ({ defaultValue: "desktop" })),
      surfaceDir: bindable<Direction | null>(() => ({ defaultValue: null })),
      hasTitle: bindable<boolean>(() => ({ defaultValue: false })),
      hasDescription: bindable<boolean>(() => ({ defaultValue: false })),
    };
  },

  computed: {
    presentation({ prop, context }) {
      const requested = prop("presentation");
      if (requested !== "auto") return requested;
      // iPhone is not `touch` and iPad is not `desktop`: the mapping is a design
      // decision per component, and here a coarse pointer gets the bottom sheet.
      return context.get("density") === "touch" ? "sheet" : "center";
    },
  },

  refs() {
    return { finalFocusEl: null };
  },

  // Pure, so the server renders the markup the client will hydrate into.
  initialState({ prop }) {
    return (prop("open") ?? prop("defaultOpen")) ? "open" : "closed";
  },

  effects: ["trackEnvironment", "trackModality"],

  watch({ context, scope, track, send, action }) {
    track(
      () => [context.get("open")],
      () => send({ type: "OPEN.SYNC" }),
    );
    // A dependency like any other, so an adapter that re-renders the title into
    // existence is in step immediately rather than one mutation record later.
    track(
      () => [hasPart(scope, "title"), hasPart(scope, "description")],
      () => action(["syncParts"]),
    );
  },

  on: {
    "TRIGGER.CLICK": { guard: "isEnabled", actions: ["openDialog"] },
    "CLOSE.CLICK": { actions: ["closeDialog"] },
    "CONTENT.DISMISS": { guard: "canDismiss", actions: ["invokeOnDismiss", "closeDialog"] },
    "CONTENT.FOCUS": { actions: ["focusInitial"] },
    "OPEN.SET": { actions: ["setOpen"] },
    "OPEN.SYNC": [{ guard: "isOpen", target: "open" }, { target: "closed" }],
    "ENVIRONMENT.SYNC": { actions: ["syncEnvironment"] },
    "PARTS.SYNC": { actions: ["syncParts"] },
  },

  states: {
    /**
     * The capture is an *exit* action rather than the `open` state's entry: the
     * interpreter installs a state's effects before running its entry actions,
     * and `hideOutside` makes the trigger's ancestor `inert`, which blurs it. By
     * then there is nothing left to remember. Leaving `closed` happens before any
     * of that (spec §3 puts it in `entry`; this is the same intent, one step
     * earlier, because the interpreter's order makes `entry` too late).
     */
    closed: { exit: ["captureFinalFocus"] },
    open: {
      effects: [
        "trackSurfaceDir",
        "trackDismissable",
        "lockPageScroll",
        "trapDialogFocus",
        "proxyTabs",
        "hideOutside",
        "captureIntents",
        "trackParts",
      ],
    },
  },

  implementations: {
    guards: {
      isEnabled: ({ prop }) => !prop("disabled"),
      isOpen: ({ context }) => context.get("open"),
      /**
       * Read live from the props rather than snapshotted into the dismissable
       * layer at install time: a consumer that flips `closeOnEscape` while the
       * dialog is open means it from that moment, not from the next open.
       */
      canDismiss({ prop, event }) {
        if (event.type !== "CONTENT.DISMISS") return false;
        if (isEscapeLikeDismissal(event.reason)) return prop("closeOnEscape");
        return prop("closeOnInteractOutside");
      },
    },

    actions: {
      openDialog({ context }) {
        context.set("open", true);
      },

      closeDialog({ context }) {
        context.set("open", false);
      },

      setOpen({ context, event }) {
        if (event.type === "OPEN.SET") context.set("open", event.open);
      },

      invokeOnDismiss({ prop, event }) {
        if (event.type === "CONTENT.DISMISS") prop("onDismiss")?.({ reason: event.reason });
      },

      captureFinalFocus({ refs, scope }) {
        const active = scope.getActiveElement();
        // `<body>` is "nobody had focus", and restoring to it at the end would be
        // indistinguishable from the browser doing nothing — except that it would
        // also cancel whatever the consumer's `finalFocus` wanted.
        refs.set("finalFocusEl", active === null || active.tagName === "BODY" ? null : active);
      },

      syncEnvironment({ context, event }) {
        if (event.type === "ENVIRONMENT.SYNC") context.set("density", event.density);
      },

      syncParts({ context, scope }) {
        context.set("hasTitle", hasPart(scope, "title"));
        context.set("hasDescription", hasPart(scope, "description"));
      },

      focusInitial({ prop, scope }) {
        const content = getContentEl(scope);
        if (content === null) return;
        focusElement(
          resolveInitialFocus(prop("initialFocus"), prop("role"), scope) ??
            getFirstTabbable(content) ??
            content,
        );
      },
    },

    effects: {
      /**
       * Machine level, not state level: the presentation has to be resolved before
       * the first open, and the tracker only reports changes — hence the seed.
       */
      /**
       * The surface is the one part that emits a `dir` nobody asked for,
       * and the portal is the whole reason. The adapter mounts it into
       * `document.body` (react/src/portal.tsx), outside whatever RTL region the
       * trigger sits in, and inheritance does not cross a portal — so the
       * direction has to be carried over explicitly. What was removed everywhere is the
       * ltr DEFAULT, not the attribute: a part still emits `dir` when the consumer
       * passes one. The default was the bug — emitting a direction nobody asked
       * for *overrode* the inheritance that already worked.
       *
       * Read from the anchor, never from the surface: the surface is in the body
       * and would only report the document's own direction back to itself. And in
       * an effect rather than in `connect`, so the server emits nothing and the
       * first client render has nothing to disagree with.
       */
      trackSurfaceDir({ prop, context, scope }) {
        context.set("surfaceDir", resolveDir(prop("dir"), getDirAnchorEl(scope)));
      },

      trackEnvironment({ scope, send }) {
        const node = getEnvironmentEl(scope);
        const onChange = (density: Density): void => send({ type: "ENVIRONMENT.SYNC", density });
        onChange(resolveEnvironment(node).density);
        return watchEnvironment(node, {
          onChange: (environment) => onChange(environment.density),
        });
      },

      /**
       * No listener, and no `data-focus-visible` on any part: the dialog's three
       * buttons take their ring from `html[data-snav-input]`, and this only has to
       * make sure the attribute is there to read. A page whose only sui component
       * is a dialog had nothing else posting it, and every ring on the surface
       * fell back to the browser heuristic that CDC §4.4 rules out.
       */
      trackModality({ scope }) {
        // Guarded rather than assumed: the unit suite runs a full open/dismiss
        // cycle with no document in the room, and what this feeds is a stylesheet
        // rule, which needs one by definition. `getDoc()` throws where the other
        // DOM effects lean on helpers that return null.
        if (scope.getRootNode() === null) return;
        return trackInputModality(scope.getDoc());
      },

      trackDismissable({ scope, prop, send }) {
        return trackDismissableLayer(getContentEl(scope), {
          id: getContentId(scope),
          type: "dialog",
          modal: prop("modal"),
          parentId: prop("parentId"),
          // Without the trigger here, clicking it to close would dismiss on
          // pointerdown and reopen on the click that follows.
          exclude: () => [getTriggerEl(scope), ...(prop("persistentElements")?.() ?? [])],
          // A literal rather than the prop, exactly like the pointer channel it
          // sits next to: the layer opens the gate, `canDismiss` decides, and it
          // reads `closeOnInteractOutside` live. Passing `prop(...)` here would
          // snapshot the answer at install time and a consumer that flips the prop
          // mid-open would not be heard until the next open.
          dismissOnFocusOutside: true,
          onDismiss: (reason) => send({ type: "CONTENT.DISMISS", reason }),
        });
      },

      // The document comes from the surface rather than from the scope: no
      // surface, nothing to lock, and no reason to demand a document exist.
      lockPageScroll({ prop, scope }) {
        if (!prop("modal") || !prop("preventScroll")) return;
        return lockScroll(getContentEl(scope)?.ownerDocument);
      },

      trapDialogFocus({ prop, refs, scope }) {
        if (!prop("trapFocus")) return;
        const content = getContentEl(scope);
        const id = getContentId(scope);
        return trapFocus(content, {
          initialFocus: () => resolveInitialFocus(prop("initialFocus"), prop("role"), scope),
          finalFocus: () => prop("finalFocus")?.() ?? refs.get("finalFocusEl"),
          restoreFocus: prop("restoreFocus"),
          loop: true,
          // A layer opened from the surface is portalled out of it and declares
          // this one as its parent: its focus is the dialog's own.
          owns: (target) =>
            content !== null && getLayerStack(content.ownerDocument).containsTarget(id, target),
        });
      },

      /**
       * The non-modal half of the pair, and mutually exclusive with the trap. Tab
       * out of a portalled surface has to land after the trigger, and the focus
       * has to come back by hand because no trap captured it on the way in. A
       * trigger disabled while open takes nothing, so `restoreFocus` falls back on
       * its neighbour (R61).
       */
      proxyTabs({ prop, refs, scope }) {
        if (prop("trapFocus")) return;
        const dispose = proxyTabFocus(getContentEl(scope), {
          triggerNode: () => getTriggerEl(scope),
        });
        if (!prop("restoreFocus")) return dispose;
        return () => {
          // Only if the user is still inside: closing a non-modal surface while
          // they are typing somewhere else must not yank the caret away.
          const content = getContentEl(scope);
          const inside = contains(content, scope.getActiveElement());
          dispose();
          if (!inside) return;
          const target = prop("finalFocus")?.() ?? refs.get("finalFocusEl");
          restoreFocus(target, content);
        };
      },

      /**
       * Three things have to be in the kept list, and each one is a bug if it is
       * missing.
       *
       * The **backdrop**, because `inert` on it swallows the pointerdown that
       * dismisses the dialog. The **positioner**, because it is the backdrop's
       * sibling: hiding everything around the backdrop marks the positioner, and
       * the positioner is the content's own parent — the surface would go inert
       * with the page. And **`persistentElements`**, because Monaco and xterm
       * mount their widgets straight onto `body`, outside the surface entirely.
       */
      hideOutside({ prop, scope }) {
        if (!prop("modal")) return;
        return hideOthers(
          [
            getContentEl(scope),
            getPositionerEl(scope),
            getBackdropEl(scope),
            ...(prop("persistentElements")?.() ?? []),
          ],
          { inert: true, layer: getContentId(scope) },
        );
      },

      /**
       * Trapped: nothing under the dialog sees a direction again until it closes.
       * Only `back` is answered. Since `@standarx/nav` 0.3.1 an unclaimed `select`
       * crosses the trap with `consumed: false`, so A and Enter still click the
       * focused control inside; every other intent a scope inside leaves unclaimed
       * (`secondary`, `contextMenu`, `scrollX`/`scrollY`, moves) is still swallowed
       * by the trap. `tabNext`/`tabPrev` escape a trap by construction because
       * Tab belongs to the focus trap.
       */
      captureIntents({ prop, scope, send }) {
        const host = prop("intents");
        const content = getContentEl(scope);
        if (host === null || host === undefined || content === null) return;
        const id = getContentId(scope);
        const stack = getLayerStack(content.ownerDocument);
        return host.pushScope(
          (event) => {
            if (event.intent !== "back") return false;
            // B and Escape share one lock: a dialog Escape cannot close must not
            // close to a gamepad either.
            if (!prop("closeOnEscape") || !stack.isTopMost(id)) return false;
            send({ type: "CONTENT.DISMISS", reason: "back" });
            return true;
          },
          // Names the surface, so a scope pushed before this one (React runs a
          // child's effect first) is still asked when its own `within` is inside.
          { trapped: true, within: () => getContentEl(scope) },
        );
      },

      trackParts({ scope, send }) {
        send({ type: "PARTS.SYNC" });
        const content = getContentEl(scope);
        const close = query(content, '[data-part~="dialog:close-trigger"]');
        warn(
          isDev() && close !== null && !hasAccessibleName(close),
          "a dialog close trigger has no accessible name — give it text, `aria-label` or `title`",
        );
        return observeChildren(content, () => send({ type: "PARTS.SYNC" }));
      },
    },
  },
});

import type { DismissReason } from "../../interaction/layer-stack";
import type { PropTypes } from "../../machine/prop-types";
import type { MachineSchema } from "../../machine/types";
import type { IntentScopeHost } from "../../nav";
import type { Density, Direction } from "../../types";

export type DialogRole = "dialog" | "alertdialog";

/** What the surface actually is once the density has had its say. */
export type DialogPresentation = "center" | "sheet";

/**
 * `drawer` is deliberately absent: it is not a presentation of this machine but
 * the Phase 7 extension that decorates it with detents and drag. `sheet-top` is
 * dropped too — it assumes a window anchor the library does not own (spec §8).
 */
export type DialogPresentationProp = "auto" | DialogPresentation;

export interface DialogOpenChangeDetails {
  readonly open: boolean;
}

export interface DialogActionTriggerProps {
  /**
   * Styling only, and deliberately not a behaviour: the button that deletes and
   * the button that saves close the dialog the same way. What changes is that the
   * reader has to be able to tell them apart before pressing.
   */
  readonly destructive?: boolean | undefined;
  /**
   * Which of the row this button is. A surface with a single action needs none —
   * the id is then the part's, as it always was — but a row of them does, or they
   * all answer to the same id (`getActionTriggerId`). Spelled `index` because
   * `getSwatchProps` already spells it that way.
   */
  readonly index?: number | undefined;
}

export interface DialogCancelTriggerProps {
  /**
   * Which of the row this way out is. Left out — which is what a surface drawing
   * one cancel does, and what every fixture written before 2026-09-06 does — the id
   * is the part's own, and that is a guarantee rather than a default:
   * `getCancelTriggerEl` reads exactly that id to open an alert on its least
   * destructive answer.
   */
  readonly index?: number | undefined;
}

export interface DialogDismissDetails {
  readonly reason: DismissReason;
}

export interface DialogMachineProps {
  /** `alertdialog` is what lets `alert-dialog` reuse this machine instead of forking it. */
  readonly role?: DialogRole | undefined;
  /** Controlled. */
  readonly open?: boolean | undefined;
  readonly defaultOpen?: boolean | undefined;
  readonly modal?: boolean | undefined;
  readonly presentation?: DialogPresentationProp | undefined;
  /** Forced off when the dialog is not modal — there is nothing to trap against. */
  readonly trapFocus?: boolean | undefined;
  readonly restoreFocus?: boolean | undefined;
  /** Ignored when the dialog is not modal. */
  readonly preventScroll?: boolean | undefined;
  /** Governs the gamepad `back` intent as well: B and Escape share one lock. */
  readonly closeOnEscape?: boolean | undefined;
  readonly closeOnInteractOutside?: boolean | undefined;
  /** Disables the trigger, not the dialog. */
  readonly disabled?: boolean | undefined;
  /** Not defaulted, deliberately: left unset the resolved page direction governs, so a subtree inside an RTL region inherits instead of being reset to `ltr`. */
  readonly dir?: Direction | undefined;
  readonly initialFocus?: (() => HTMLElement | null) | undefined;
  readonly finalFocus?: (() => HTMLElement | null) | undefined;
  /**
   * Nodes that live outside the surface but belong to it — Monaco and xterm mount
   * widgets straight onto `body`. They are excluded from `hideOthers` and from the
   * outside-detection, so they stay usable and clicking one does not dismiss.
   */
  readonly persistentElements?: (() => readonly HTMLElement[]) | undefined;
  /** The layer this one opened from. Declared, because the DOM cannot tell once portalled. */
  readonly parentId?: string | undefined;
  readonly describedBy?: string | undefined;
  /** The accessible name used when no `title` part is rendered. */
  readonly label?: string | undefined;
  /**
   * Where the gamepad scope is pushed. The core owns no singleton, so the adapter
   * hands the `InputSystem` in — same contract as `pushEngageScope`. Without one
   * the gamepad drives nothing and the keyboard still works, because Escape comes
   * from the dismissable layer and not from the bus.
   */
  readonly intents?: IntentScopeHost | null | undefined;
  readonly onOpenChange?: ((details: DialogOpenChangeDetails) => void) | undefined;
  readonly onDismiss?: ((details: DialogDismissDetails) => void) | undefined;
}

export interface ResolvedDialogMachineProps extends DialogMachineProps {
  readonly role: DialogRole;
  readonly defaultOpen: boolean;
  readonly modal: boolean;
  readonly presentation: DialogPresentationProp;
  readonly trapFocus: boolean;
  readonly restoreFocus: boolean;
  readonly preventScroll: boolean;
  readonly closeOnEscape: boolean;
  readonly closeOnInteractOutside: boolean;
  readonly disabled: boolean;
  readonly intents: IntentScopeHost | null;
}

export interface DialogSchema extends MachineSchema {
  state: "open" | "closed";
  props: ResolvedDialogMachineProps;
  context: {
    /**
     * The single source of truth. The state is only a projection of it, made by
     * the watch — which is what makes the controlled semantics free: a consumer
     * that refuses to update `open` keeps the dialog open, and that is correct.
     */
    open: boolean;
    density: Density;
    /**
     * The direction the portalled surface is drawn in, resolved from the anchor
     * when it opens. `null` until then — and on the server — which is what keeps
     * the first client render agreeing with the markup it hydrates.
     */
    surfaceDir: Direction | null;
    hasTitle: boolean;
    hasDescription: boolean;
  };
  computed: { presentation: DialogPresentation };
  refs: {
    /**
     * Who had focus when the dialog opened. Needed because the non-modal path
     * installs no focus trap (the trap captures its own), and because the trigger
     * can be unmounted while the dialog is open — a confirm/prompt queue does
     * exactly that.
     */
    finalFocusEl: HTMLElement | null;
  };
  event:
    | { type: "TRIGGER.CLICK" }
    | { type: "CLOSE.CLICK" }
    | { type: "CONTENT.DISMISS"; reason: DismissReason }
    | { type: "CONTENT.FOCUS" }
    | { type: "OPEN.SET"; open: boolean }
    | { type: "OPEN.SYNC" }
    | { type: "ENVIRONMENT.SYNC"; density: Density }
    | { type: "PARTS.SYNC" };
  action:
    | "openDialog"
    | "closeDialog"
    | "setOpen"
    | "invokeOnDismiss"
    | "captureFinalFocus"
    | "syncEnvironment"
    | "syncParts"
    | "focusInitial";
  guard: "isEnabled" | "isOpen" | "canDismiss";
  effect:
    | "trackEnvironment"
    | "trackModality"
    | "trackSurfaceDir"
    | "trackDismissable"
    | "lockPageScroll"
    | "trapDialogFocus"
    | "proxyTabs"
    | "hideOutside"
    | "captureIntents"
    | "trackParts";
}

export interface DialogApi<T extends PropTypes = PropTypes> {
  readonly open: boolean;
  readonly modal: boolean;
  readonly presentation: DialogPresentation;
  setOpen(open: boolean): void;
  /**
   * Asks to close *for a reason*, which is what `setOpen(false)` cannot do: that
   * one skips `canDismiss` and never calls `onDismiss`, so a surface configured to
   * refuse dismissal would be closed anyway and a consumer listening for why would
   * hear nothing. The path a decorator uses — `drawer` sends `"drag"` — and useful
   * to any future one.
   */
  dismiss(reason: DismissReason): void;
  /**
   * Replays the initial focus without closing. A queue that swaps one question
   * for the next keeps the same dialog mounted, and the new question has to get
   * the focus the way the first one did.
   */
  focusInitial(): void;
  getTriggerProps(): T["button"];
  getBackdropProps(): T["element"];
  getPositionerProps(): T["element"];
  getContentProps(): T["element"];
  getTitleProps(): T["element"];
  getDescriptionProps(): T["element"];
  getCloseTriggerProps(): T["button"];
  /** `alert-dialog`'s three: the row, then the two buttons it lays out. */
  getActionsProps(): T["element"];
  getCancelTriggerProps(props?: DialogCancelTriggerProps): T["button"];
  getActionTriggerProps(props?: DialogActionTriggerProps): T["button"];
}

/**
 * `<Dialog title="…"/>` — the surface a consumer would otherwise write in nine
 * parts, and the reason the bare name is not `DialogRoot`: the root renders no
 * element at all (`dialog.anatomy.ts` has no `root` part), so `<DialogRoot>` is a
 * context and `<Dialog>` is the trigger, the scrim, the positioner, the surface
 * and everything on it.
 *
 * It is a placement and nothing else — no state, no memo, no prop getter rewritten.
 * The focus trap, the scroll lock, the layer stack and the gamepad scope are the
 * machine's, unchanged, and that is the whole point of the shape: `ConfirmDialog`
 * in the reference app is the app's only modal and it has no focus trap, so what closes that
 * gap is not a new behaviour but a form short enough that nobody writes their own.
 *
 * Three translations the type system cannot make on its own:
 *
 *  - **`title` is required.** `getContentProps` names the surface from the title
 *    part when the machine has read one out of the DOM and from `label` when it
 *    has not — so a dialog with neither is nameless. The part is placed here
 *    unconditionally, which also means `label` is never the name a composed
 *    dialog ends up with: pass the words to `title`.
 *  - **`closeLabel` is a name, not a slot.** `getCloseTriggerProps` writes an id,
 *    a type, a state and a click handler and no accessible name at all — so the
 *    part is rendered only once the consumer has named it, and its children stay
 *    empty for `_dialog.scss` to paint the ✕ under `:empty`. The rule
 *    `MenuContent.cancelLabel` already applies: pass the word and the part
 *    appears, leave it out and nothing is added, because a nameless button is
 *    worse than none.
 *  - **`actions` is the alert's row, and it works under either role.**
 *    `AlertDialogActions`, `AlertDialogAction` and `AlertDialogCancel` read
 *    the dialog context `DialogRoot` publishes — not one of their own — and their part
 *    tokens are `dialog:actions`, `dialog:action-trigger`, `dialog:cancel-trigger`.
 *    They are alert-named React components over dialog parts, so a plain dialog
 *    that ends in Save/Cancel gets the same row, laid out by the same rule.
 */

import { isDev, warn } from "@standarui/core";
import type { ReactNode } from "react";
import type { ComposedAction, ComposedTrigger } from "../../composed";
import type { PartProps } from "../../create-part";
import type { PortalProps } from "../../portal";
import {
  AlertDialogAction,
  type AlertDialogActionProps,
  AlertDialogActions,
  AlertDialogCancel,
} from "../alert-dialog/alert-dialog";
import {
  DialogBackdrop,
  DialogCloseTrigger,
  DialogContent,
  DialogDescription,
  DialogPortal,
  type DialogPortalProps,
  DialogPositioner,
  DialogRoot,
  DialogTitle,
  DialogTrigger,
  type UseDialogProps,
} from "./dialog";

/**
 * The escape hatch, applied **last** on every part: what the layer defaults is a
 * default, and the consumer's entry wins over it.
 *
 * Eleven keys: the ten parts of `dialog.anatomy.ts`, all of which this layer can
 * place, plus `portal` — which is no part at all but the React container the parts
 * form wraps the surface in. The last three (`actions`, `cancelTrigger`,
 * `actionTrigger`) reach the alert's row, which exists only where `actions` does.
 */
export interface DialogParts {
  readonly trigger?: PartProps<"button"> | undefined;
  readonly portal?: DialogPortalProps | undefined;
  readonly backdrop?: PartProps<"div"> | undefined;
  readonly positioner?: PartProps<"div"> | undefined;
  readonly content?: PartProps<"div"> | undefined;
  readonly title?: PartProps<"h2"> | undefined;
  readonly description?: PartProps<"p"> | undefined;
  readonly closeTrigger?: PartProps<"button"> | undefined;
  readonly actions?: PartProps<"div"> | undefined;
  /**
   * Applied to EVERY cancel entry of `actions`, hence no `id` **and no IDREF**:
   * one id repeated down a row is a broken reference per button, and one
   * `aria-labelledby` repeated gives every button the same name — which no
   * dangling-IDREF check can see, because the id it points at does resolve. `ref`
   * goes for the same reason: a single ref held by N buttons ends up holding the
   * last one.
   */
  readonly cancelTrigger?:
    | Omit<
        PartProps<"button">,
        "id" | "ref" | "aria-labelledby" | "aria-describedby" | "aria-controls"
      >
    | undefined;
  /**
   * Applied to EVERY non-cancel entry of `actions`. `destructive` is left out on
   * top of the repeated-key list: it is the entry's own field, and one flag here
   * would paint every action in the row destructive at once. `index` is left out
   * for the sharper version of the same reason — it is applied last, so one value
   * here would mint the same id for every button in the row, which is the exact
   * defect the key was added to close.
   */
  readonly actionTrigger?:
    | Omit<
        AlertDialogActionProps,
        | "destructive"
        | "index"
        | "id"
        | "ref"
        | "aria-labelledby"
        | "aria-describedby"
        | "aria-controls"
      >
    | undefined;
}

export interface DialogComposedProps extends UseDialogProps {
  /**
   * Handed to `DialogTrigger` as `render` — never as its children. The trigger
   * *is* a `<button>`, and a button inside a button is `nested-interactive`.
   * Left out, no trigger part is placed at all, which is the shape a dialog
   * driven from a store takes: `open` on one side, no anchor on the other.
   */
  readonly trigger?: ComposedTrigger | undefined;
  /**
   * The surface's accessible name, and required for that reason — a dialog
   * without one is a defect rather than a choice. The part is always placed, so
   * the machine's `label` fallback is never what a composed dialog is named by:
   * an empty title is not a dialog named by something else, it is a dialog named
   * by nothing.
   *
   * `ReactNode` alone did not say that — it admits `null`, `undefined` and
   * `false`, so `<Dialog title={cond && "…"}/>` typechecked its way to a nameless
   * modal. Those three are excluded here. The empty *string* cannot be excluded by
   * a type (`Exclude<string, "">` is still `string`), so it is refused at runtime
   * below, in dev only, the way the machine's own name guards are.
   */
  readonly title: Exclude<ReactNode, null | undefined | boolean>;
  /** Wired to `aria-describedby` by the machine, once it has read the part. */
  readonly description?: ReactNode;
  /** The body: the form, the list, whatever the question is about. */
  readonly children?: ReactNode;
  /**
   * The row of answers. `cancel: true` becomes `AlertDialogCancel` — which is
   * also where an alert dialog opens its focus — and everything else becomes
   * `AlertDialogAction`, carrying `destructive` through to the attribute the
   * sheet paints. `onPress` lands on the button's `onClick`, so it runs *before*
   * the machine's own handler and a `preventDefault()` inside it keeps the
   * surface open, which is the contract `getActionTriggerProps` publishes.
   *
   * The order is the array's, never sorted: the APG asks an alert to open its
   * focus on the least destructive action and the machine does that by looking
   * the cancel button up by id, so writing the confirm first — the way the
   * sentence reads — costs nothing.
   *
   * **As many answers as the question has.** Each action carries its `index`, so
   * the ids are distinct however long the row is — until 2026-09-05 the third button repeated
   * the second one's id. A row with two ways out repeated it for one day longer:
   * the cancel half is keyed from the *second* one on, because the first has to
   * keep the id the initial-focus rule two paragraphs up resolves.
   */
  readonly actions?: readonly ComposedAction[] | undefined;
  /**
   * Names the close button, and the part is placed only when it is given: the
   * machine emits no accessible name for it (`getCloseTriggerProps` — id, type,
   * state, click, and nothing else). Present, the part is rendered *empty* and
   * carries `aria-label`, so the sheet draws the ✕ under `:empty` and a consumer
   * who wants their own glyph reaches it through `parts.closeTrigger`.
   *
   * The empty string counts as absent, not as a name. The guard used to be
   * `== null`, so `closeLabel=""` placed a painted ✕ carrying `aria-label=""` —
   * a button with no name at all, which is the one outcome withholding the part
   * exists to prevent.
   */
  readonly closeLabel?: string | undefined;
  readonly container?: PortalProps["container"] | undefined;
  readonly parts?: DialogParts | undefined;
}

export function Dialog(props: DialogComposedProps): ReactNode {
  const { trigger, title, description, children, actions, closeLabel, container, parts, ...root } =
    props;

  // Which entry keeps the un-indexed id: an alert opens its focus on whatever
  // `getCancelTriggerEl` resolves, and that is the part's own id. Read here rather
  // than counted in the map because the row is commonly written confirm-first, so
  // the first way out is rarely entry 0.
  const firstCancel = actions?.findIndex((action) => action.cancel === true) ?? -1;

  // The half the type cannot state. `Exclude<ReactNode, …>` keeps out `null`,
  // `undefined` and `false`; no type keeps out `""`, and a title part rendered
  // empty is a modal named by nothing — the machine's `label` fallback never runs,
  // because the part is always placed.
  warn(
    isDev() && title === "",
    'Dialog: `title` is the surface\'s accessible name and cannot be "". Pass the words, or write the parts and name the content yourself.',
  );

  return (
    <DialogRoot {...root}>
      {trigger === undefined ? null : <DialogTrigger render={trigger} {...parts?.trigger} />}
      <DialogPortal container={container} {...parts?.portal}>
        <DialogBackdrop {...parts?.backdrop} />
        <DialogPositioner {...parts?.positioner}>
          <DialogContent {...parts?.content}>
            {/* First, and that is the whole of the placement: `_dialog.scss` gives
                this button `justify-self: end` in whichever grid row the DOM order
                puts it, so a composed surface asks for the corner by asking for it
                first. The parts layer keeps the other reading — the same part after
                a row of actions is "Close" at the end of it — and the sheet still
                does not have to know which of the two it is drawing. */}
            {closeLabel == null || closeLabel === "" ? null : (
              <DialogCloseTrigger aria-label={closeLabel} {...parts?.closeTrigger} />
            )}
            <DialogTitle {...parts?.title}>{title}</DialogTitle>
            {description == null ? null : (
              <DialogDescription {...parts?.description}>{description}</DialogDescription>
            )}
            {children}
            {actions === undefined ? null : (
              <AlertDialogActions {...parts?.actions}>
                {actions.map((action, index) =>
                  action.cancel === true ? (
                    <AlertDialogCancel
                      key={action.label}
                      index={index === firstCancel ? undefined : index}
                      onClick={action.onPress}
                      {...parts?.cancelTrigger}
                    >
                      {action.label}
                    </AlertDialogCancel>
                  ) : (
                    <AlertDialogAction
                      key={action.label}
                      index={index}
                      destructive={action.destructive}
                      onClick={action.onPress}
                      {...parts?.actionTrigger}
                    >
                      {action.label}
                    </AlertDialogAction>
                  ),
                )}
              </AlertDialogActions>
            )}
          </DialogContent>
        </DialogPositioner>
      </DialogPortal>
    </DialogRoot>
  );
}

/**
 * The dialog in React: a machine in the root, a portalled surface, and two
 * presences so the scrim and the surface each finish their own exit.
 *
 * **The root renders no element.** The anatomy has no `root` part — the trigger
 * stays where the author wrote it and the surface is portalled elsewhere, so the
 * two are siblings with nothing above them. What the annexe called `root` is this
 * context, which is the adapter's business (spec §8, divergence 1).
 *
 * Two things are wired here that a consumer should never have to wire by hand: the
 * intent scope the gamepad's B button travels on, taken from the nearest
 * `<NavProvider>`, and the parenthood of a surface opened from inside another
 * one — declared, because once both are portalled the DOM cannot tell.
 *
 * That parenthood travels on `layer-context`, which is shared with every other
 * overlay family rather than owned here: what opens inside a dialog is as often a
 * popover or a menu as another dialog, and a private context would only chain the
 * cases that happen to be the same component.
 */

import type { Service } from "@standarui/core";
import * as dialog from "@standarui/core/dialog";
import { type ReactNode, type Ref, useMemo } from "react";
import { composeRefs } from "../../compose-refs";
import { createPart, type PartProps } from "../../create-part";
import { useEnvironment } from "../../environment";
import { LayerProvider, useParentLayerId } from "../../layer-context";
import { useIntentScopeHost } from "../../nav";
import { normalizeProps, type ReactPropTypes } from "../../normalize-props";
import { createPartContext } from "../../part-context";
import { Portal, type PortalProps } from "../../portal";
import { type PresenceApi, usePresence } from "../../presence";
import { type MachineRuntimeProps, useMachine } from "../../use-machine";
import { useRender } from "../../use-render";

export type DialogApi = dialog.DialogApi<ReactPropTypes>;

export interface UseDialogProps extends dialog.DialogMachineProps, MachineRuntimeProps {}

interface DialogContextValue {
  readonly api: DialogApi;
  /** Keeps the surface in the tree while closed; the consumer hides it in CSS. */
  readonly keepMounted: boolean;
  readonly backdrop: PresenceApi;
  readonly content: PresenceApi;
}

const DialogContext = createPartContext<DialogContextValue>("Dialog");

function useDialogService(props: UseDialogProps): Service<dialog.DialogSchema> {
  const parentLayerId = useParentLayerId();
  const host = useIntentScopeHost();

  return useMachine(dialog.machine, {
    ...props,
    // `??` would override an explicit `null`, and `null` is how a consumer says
    // "this dialog answers no gamepad" while a provider is mounted above it.
    intents: props.intents === undefined ? host : props.intents,
    parentId: props.parentId ?? parentLayerId,
  });
}

export function useDialog(props: UseDialogProps): DialogApi {
  return dialog.connect(useDialogService(props), normalizeProps);
}

/** The api of the dialog a subtree sits in — the queue case of spec §9.4 reads it. */
export function useDialogContext(): DialogApi {
  return DialogContext.usePart("DialogContext").api;
}

export interface DialogRootProps extends UseDialogProps {
  readonly keepMounted?: boolean | undefined;
  readonly children?: ReactNode;
}

export function DialogRoot(props: DialogRootProps): ReactNode {
  const { children, keepMounted, ...machineProps } = props;
  const service = useDialogService(machineProps);
  const api = dialog.connect(service, normalizeProps);
  const { motion } = useEnvironment();

  // `motion === "none"` and not `reducedMotion`, because the two are not the same
  // question. `reduced` keeps every duration and only flattens the movement — the
  // fade is the whole point of that mode — so skipping the wait there throws the
  // surface out before the crossfade the sheet deliberately kept can play. Only
  // `none` zeroes the durations, and there the wait has nothing to wait for.
  const immediate = motion === "none";

  // Two presences, not one. The scrim and the surface run different exits — 200 ms
  // against 150 or 250 (motion.md §2.5) — and a single presence can only measure
  // the animations of the one node it holds, so it would cut the other one short.
  const backdrop = usePresence({ present: api.open, immediate });
  const content = usePresence({ present: api.open, immediate });

  const value: DialogContextValue = {
    api,
    keepMounted: keepMounted === true,
    backdrop,
    content,
  };

  // Outside the dialog's own context, because what reads it is not a dialog part:
  // it is whatever surface a consumer opens from inside this one.
  return (
    <LayerProvider layerId={dialog.getContentId(service.scope)}>
      <DialogContext.Provider value={value}>{children}</DialogContext.Provider>
    </LayerProvider>
  );
}

/**
 * Mounted the moment the machine says open, rather than when the presence catches
 * up — and that is not an optimisation.
 *
 * `usePresence` learns of a change in a layout effect, which is one commit late,
 * and one commit is too late: the interpreter installs the open state's effects in
 * the layout effect of the very commit that opened it, and the focus trap, the
 * dismissable layer, the scroll lock and `hideOthers` all look the surface up by
 * id. A surface arriving a commit later would find every one of them installed
 * against nothing, with nothing to re-install them. So the open direction is read
 * straight off the machine; the presence only ever extends the mount past the close.
 */
function isMounted(context: DialogContextValue, presence: PresenceApi): boolean {
  return context.keepMounted || context.api.open || presence.present;
}

function usePresenceRef(
  presence: PresenceApi,
  consumer: Ref<HTMLElement> | undefined,
): Ref<HTMLElement> {
  // Memoised on identity: a fresh callback every render would make React detach and
  // re-attach the consumer's own ref on every render too.
  return useMemo(() => composeRefs(presence.ref, consumer), [presence.ref, consumer]);
}

export const DialogTrigger: (props: PartProps<"button">) => ReactNode = createPart(DialogContext, {
  name: "DialogTrigger",
  element: "button",
  props: (context) => context.api.getTriggerProps(),
});

export interface DialogPortalProps extends Omit<PortalProps, "children"> {
  readonly children?: ReactNode;
}

export function DialogPortal(props: DialogPortalProps): ReactNode {
  const { children, ...portalProps } = props;
  const context = DialogContext.usePart("DialogPortal");
  const present = isMounted(context, context.backdrop) || isMounted(context, context.content);
  return present ? <Portal {...portalProps}>{children}</Portal> : null;
}

export function DialogBackdrop(props: PartProps<"div">): ReactNode {
  const { render, asChild, children, ref, ...elementProps } = props;
  const context = DialogContext.usePart("DialogBackdrop");
  const composed = usePresenceRef(context.backdrop, ref);

  const element = useRender({
    render,
